def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    base = 34.0

    if supply <= 16:
        base += 18.0
    elif supply <= 18:
        base += 10.0
    elif supply >= 23:
        base -= 8.0

    if hp <= 2:
        base += 28.0
    elif hp <= 4:
        base += 16.0
    elif hp >= 8:
        base -= 4.0

    if no_water_days >= 2:
        base += 26.0
    elif no_water_days >= 1:
        base += 14.0

    if urgent_opp >= 2:
        base += 8.0
    elif urgent_opp == 0 and supply >= 20:
        base -= 5.0

    if highest_prev >= 130.0:
        if hp > 4 and no_water_days == 0:
            base = min(base, 28.0)
        else:
            base += 10.0
    elif highest_prev >= 80.0:
        base = max(base, min(highest_prev + 2.0, 78.0))
    elif highest_prev >= 55.0:
        base = max(base, highest_prev + 1.5)
    elif avg_prev > 0:
        base = max(base, avg_prev + 1.0)

    if day >= 8:
        base += 6.0
    if day == 10:
        base += 10.0

    if budget < 45:
        base = min(base, budget)
    elif budget < 90:
        base = min(base, 0.8 * budget)
    else:
        base = min(base, 0.55 * budget)

    base = max(0.0, min(base, budget))
    return float(round(base, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return 1.0

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
        if supply < (len(alive_opponents) + 1) * WATER_REQ:
            return min(my_status['budget'], max(avg_prev * 1.1, DAILY_SALARY * 0.6))
        else:
            return min(my_status['budget'], max(avg_prev * 0.8, DAILY_SALARY * 0.3))

    return min(my_status['budget'], DAILY_SALARY * 0.5)
